var now = DateTimeOffset.Now;
var events = new List<ArcTimelineEvent>
{
    new()
    {
        Id = "e1",
        At = now.AddMinutes(-12),
        Actor = "Maya Chen",
        Title = "merged Checkout redesign into main",
        Meta = "PR #482",
        Tone = ArcTimelineTone.Success
    },
    new()
    {
        Id = "e2",
        At = now.AddMinutes(-41),
        Title = "Deploy failed",
        Tone = ArcTimelineTone.Danger,
        Icon = "triangle-alert",
        Detail = "error: Type 'OrderSummary' is missing properties: total, currency"
    }
};

var timeline = new ArcTimeline
{
    Events = events,
    Now = now,
    Label = "Project activity",
    DefaultExpanded = new[] { "e2" }
};
